type LayoutPreset = { id: string; name: string; role: Role; widgets: WidgetId[] };
const DEFAULT_PREFERENCES: UserPreferences = { defaultFilters: EMPTY_FILTERS, widgets: [...WIDGETS], name: "", defaultPage: "dashboard" };
const ROLE_PRESETS: Record<Role, LayoutPreset[]> = { admin: [{ id: "admin-qa", name: "QA command center", role: "admin", widgets: ["sentiment", "trend", "themes", "heatmap", "evidence", "language"] }, { id: "admin-executive", name: "Executive brief", role: "admin", widgets: ["sentiment", "trend", "evidence", "themes", "heatmap", "language"] }], viewer: [{ id: "viewer-evidence", name: "Evidence first", role: "viewer", widgets: ["evidence", "sentiment", "trend", "themes", "language", "heatmap"] }, { id: "viewer-language", name: "Voice of customer", role: "viewer", widgets: ["language", "sentiment", "evidence", "themes", "trend", "heatmap"] }] };
const SHARED_PRESET_KEY = "siq_shared_layout_presets_v1";
const LAYOUT_DB_NAME = "sentimentiq-workspace";
const LAYOUT_DB_VERSION = 1;
const LAYOUT_STORE_NAME = "layout-presets";
function getLegacyLayoutPresets(user: User): LayoutPreset[] { try { const saved = JSON.parse(localStorage.getItem(SHARED_PRESET_KEY) ?? "[]"); return Array.isArray(saved) ? saved.filter((preset) => preset.role === user.role) : []; } catch { return []; } }
function getLayoutPresets(user: User): LayoutPreset[] { const legacy = getLegacyLayoutPresets(user); return [...ROLE_PRESETS[user.role], ...legacy]; }
function openLayoutDb(): Promise<IDBDatabase> { return new Promise((resolve, reject) => { if (typeof indexedDB === "undefined") { reject(new Error("IndexedDB is unavailable in this browser.")); return; } const request = indexedDB.open(LAYOUT_DB_NAME, LAYOUT_DB_VERSION); request.onupgradeneeded = () => { if (!request.result.objectStoreNames.contains(LAYOUT_STORE_NAME)) request.result.createObjectStore(LAYOUT_STORE_NAME, { keyPath: "id" }); }; request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error ?? new Error("Unable to open workspace storage.")); }); }
function readIndexedPresets(user: User): Promise<LayoutPreset[]> { return openLayoutDb().then((db) => new Promise((resolve, reject) => { const request = db.transaction(LAYOUT_STORE_NAME, "readonly").objectStore(LAYOUT_STORE_NAME).getAll(); request.onsuccess = () => { db.close(); const presets = request.result as LayoutPreset[]; resolve(user.role === "admin" ? presets : presets.filter((preset) => preset.role === user.role)); }; request.onerror = () => { db.close(); reject(request.error ?? new Error("Unable to read workspace presets.")); }; })); }
function writeIndexedPresets(user: User, presets: LayoutPreset[]): Promise<void> { return openLayoutDb().then((db) => new Promise((resolve, reject) => { const transaction = db.transaction(LAYOUT_STORE_NAME, "readwrite"); const store = transaction.objectStore(LAYOUT_STORE_NAME); const custom = presets.filter((preset) => !ROLE_PRESETS[user.role].some((defaultPreset) => defaultPreset.id === preset.id)); custom.forEach((preset) => store.put(preset)); transaction.oncomplete = () => { db.close(); resolve(); }; transaction.onerror = () => { db.close(); reject(transaction.error ?? new Error("Unable to save workspace presets.")); }; })); }
async function loadLayoutPresets(user: User): Promise<LayoutPreset[]> { try { const indexed = await readIndexedPresets(user); if (indexed.length) return [...ROLE_PRESETS[user.role], ...indexed]; const legacy = getLegacyLayoutPresets(user); if (legacy.length) await writeIndexedPresets(user, legacy); return [...ROLE_PRESETS[user.role], ...legacy]; } catch { return getLayoutPresets(user); } }
async function saveLayoutPresets(user: User, presets: LayoutPreset[]) { try { const db = await openLayoutDb(); await new Promise<void>((resolve, reject) => { const transaction = db.transaction(LAYOUT_STORE_NAME, "readwrite"); const store = transaction.objectStore(LAYOUT_STORE_NAME); const request = store.getAll(); request.onsuccess = () => { const current = request.result as LayoutPreset[]; const custom = presets.filter((preset) => !Object.values(ROLE_PRESETS).flat().some((defaultPreset) => defaultPreset.id === preset.id)); const roleIds = new Set(custom.map((preset) => preset.id)); current.filter((preset) => !Object.values(ROLE_PRESETS).flat().some((defaultPreset) => defaultPreset.id === preset.id) && (user.role === "admin" || preset.role === user.role) && !roleIds.has(preset.id)).forEach((preset) => store.delete(preset.id)); custom.forEach((preset) => store.put(preset)); }; request.onerror = () => reject(request.error ?? new Error("Unable to read workspace presets.")); transaction.oncomplete = () => resolve(); transaction.onerror = () => reject(transaction.error ?? new Error("Unable to save workspace presets.")); }); db.close(); } catch { /* Keep the dashboard usable if IndexedDB is unavailable. */ } }
function getPreferences(user: User): UserPreferences { try { return { ...DEFAULT_PREFERENCES, ...(JSON.parse(localStorage.getItem(`siq_preferences_${user.id}`) ?? "{}")), defaultFilters: { ...EMPTY_FILTERS, ...(JSON.parse(localStorage.getItem(`siq_preferences_${user.id}`) ?? "{}").defaultFilters ?? {}) }, name: user.name }; } catch { return { ...DEFAULT_PREFERENCES, name: user.name }; } }
function savePreferences(user: User, preferences: UserPreferences) { localStorage.setItem(`siq_preferences_${user.id}`, JSON.stringify(preferences)); }
function interpretNaturalQuery(query: string, reviews: Review[]) {
  const normalized = query.toLowerCase().trim();
  const sentiment: Sentiment | null = /negative|bad|angry|frustrat|complaint|issue|problem/.test(normalized) ? "negative" : /positive|good|great|happy|love|recommend|delight/.test(normalized) ? "positive" : /neutral|mixed|unsure|ambivalent/.test(normalized) ? "neutral" : null;
  const theme = Object.keys(THEME_LABELS).find((key) => normalized.includes(key) || normalized.includes(THEME_LABELS[key].toLowerCase()));
  const ratingMatch = normalized.match(/([1-5])\s*(?:star|\/\s*5)|rating\s*(?:of\s*)?([1-5])/);
  const rating = Number(ratingMatch?.[1] ?? ratingMatch?.[2]) || null;
  const product = reviews.map((review) => review.product).find((candidate) => normalized.includes(candidate.toLowerCase()));
  const recentDays = /today|today's/.test(normalized) ? 1 : /this week|last week/.test(normalized) ? 7 : /this month|last month/.test(normalized) ? 31 : null;
  const cutoff = recentDays ? new Date(Date.now() - recentDays * 86400000).toISOString().slice(0, 10) : null;
  const matches = reviews.filter((review) => {
    const effective = getEffectiveSentiment(review);
    const haystack = `${review.text} ${review.product} ${review.customer} ${review.source} ${review.themes.join(" ")}`.toLowerCase();
    return (!sentiment || effective === sentiment) && (!theme || review.themes.includes(theme)) && (!rating || review.rating === rating) && (!product || review.product === product) && (!cutoff || review.date >= cutoff) && (!sentiment && !theme && !rating && !product && !cutoff ? haystack.includes(normalized) : true);
  });
  const parts = [sentiment ? `${sentiment} sentiment` : "all sentiment", theme ? `${THEME_LABELS[theme]} theme` : null, rating ? `${rating}-star reviews` : null, product ? product : null, cutoff ? `from the last ${recentDays} days` : null].filter(Boolean);
  return { matches, summary: parts.length ? `Showing ${parts.join(" · ")}` : "Showing text matches" };
}

