function ThemeToggle({ dark, onToggle }: { dark: boolean; onToggle: () => void }) {
  return <button type="button" className="theme-toggle" onClick={onToggle} aria-label={`Switch to ${dark ? "light" : "dark"} mode`}><span className={dark ? "" : "active"}><Sun size={14} /></span><span className={dark ? "active" : ""}><Moon size={14} /></span></button>;
}

function NaturalSearch({ reviews, onOpenReviews }: { reviews: Review[]; onOpenReviews: (matches: Review[], query: string) => void }) {
  const [query, setQuery] = useState("");
  const [focused, setFocused] = useState(false);
  const [result, setResult] = useState<{ matches: Review[]; summary: string } | null>(null);
  const run = () => { if (!query.trim()) return; setResult(interpretNaturalQuery(query, reviews)); };
  return <div className={`natural-search ${focused ? "focused" : ""}`}><Sparkles size={15} /><input value={query} onFocus={() => setFocused(true)} onChange={(event) => { setQuery(event.target.value); setResult(null); }} onKeyDown={(event) => { if (event.key === "Enter") run(); if (event.key === "Escape") { setFocused(false); setResult(null); } }} placeholder="Ask the signal… e.g. negative shipping reviews" aria-label="Ask the signal in natural language" /><button type="button" onClick={run} aria-label="Run natural language search"><Search size={14} /></button>{focused && <div className="natural-search-popover"><div className="search-ai-label"><Sparkles size={13} /> Natural-language search</div>{result ? <><strong>{result.matches.length.toLocaleString()} matches</strong><span>{result.summary}</span><button type="button" className="text-button" onClick={() => onOpenReviews(result.matches, query)}>Open in Reviews Explorer <ChevronRight size={13} /></button></> : <><span>Try “show negative reviews about shipping” or “find 5-star feedback this month”.</span><small>Interprets intent locally, then keeps the review evidence inspectable.</small></>}</div>}</div>;
}

